import { defineApp } from "convex/server";
import rateLimiter from "@convex-dev/rate-limiter/convex.config.js";

const app = defineApp();
app.use(rateLimiter);

export default app;

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

const runId = process.env.ZEALT_RUN_ID || "";
const runIdWithUnderscores = runId.replace(/-/g, "_");
const messagesTableName = `messages_${runIdWithUnderscores}`;

export default defineSchema({
  [messagesTableName]: defineTable({
    userId: v.string(),
    text: v.string(),
  }),
});

import { mutation } from "./_generated/server";
import { v } from "convex/values";
import { RateLimiter } from "@convex-dev/rate-limiter";
import { components } from "./_generated/api";

const rateLimiter = new RateLimiter(components.rateLimiter, {
  sendMessage: { kind: "fixed window", rate: 3, period: 10000 },
});

export const sendMessage = mutation({
  args: {
    userId: v.string(),
    text: v.string(),
  },
  handler: async (ctx, args) => {
    const runId = process.env.ZEALT_RUN_ID || "";
    const runIdWithUnderscores = runId.replace(/-/g, "_");
    const tableName = `messages_${runIdWithUnderscores}`;

    const rateLimitKey = `${runId}_${args.userId}`;

    const status = await rateLimiter.limit(ctx, "sendMessage", {
      key: rateLimitKey,
    });

    if (!status.ok) {
      throw new Error("Rate limit exceeded");
